// never incremented from a client request.\n  responseRate        Float  @default(0)\n  avgResponseMinutes  Int?\n  completedJobs       Int    @default(0)\n  cancelledJobs       Int    @default(0)\n  noShowCount         Int    @default(0)\n  ratingAvg           Float  @default(0)\n  ratingCount         Int    @default(0)\n  totalEarningsPoisha BigInt @default(0)\n  pendingPayoutPoisha BigInt @default(0)\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  user          User                            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  verifications ProviderVerification[]\n  services      ProviderService[]\n  serviceAreas  ProviderServiceArea[]\n  availability  ProviderAvailability[]\n  exceptions    ProviderAvailabilityException[]\n  timeOff       ProviderTimeOff[]\n  portfolio     PortfolioItem[]\n  bookings      Booking[]\n  payments      Payment[]\n  payouts       Payout[]\n  payoutMethods ProviderPayoutMethod[]\n  reviews       Review[]\n  complaints    Complaint[]\n  conversations Conversation[]\n  savedBy       SavedProvider[]\n\n  @@index([status, isSponsored])\n  @@index([ratingAvg, completedJobs])\n  @@index([createdAt])\n  @@index([deletedAt])\n  @@index([searchText(ops: raw(\"gin_trgm_ops\"))], type: Gin, map: \"provider_profiles_search_trgm_idx\")\n  @@index([searchSkeleton(ops: raw(\"gin_trgm_ops\"))], type: Gin, map: \"provider_profiles_search_skel_idx\")\n  @@map(\"provider_profiles\")\n}\n\n/// One row per verification type. A badge is rendered only when a row here has\n/// status APPROVED, so badges can never appear without a real verification.\nmodel ProviderVerification {\n  id                String             @id @default(cuid())\n  providerProfileId String\n  type              VerificationType\n  status            VerificationStatus @default(PENDING)\n  /// Private object-storage keys. Never public URLs.\n  documentKeys      String[]           @default([])\n  documentMeta      Json?\n  rejectionReason   String?\n  reviewedByUserId  String?\n  reviewedAt        DateTime?\n  expiresAt         DateTime?\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n  reviewedBy      User?           @relation(\"VerificationReviewedBy\", fields: [reviewedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([providerProfileId, type, status])\n  @@index([status, createdAt])\n  @@map(\"provider_verifications\")\n}\n\nmodel ProviderService {\n  id                 String    @id @default(cuid())\n  providerProfileId  String\n  serviceId          String\n  priceMode          PriceMode @default(FIXED)\n  basePricePoisha    Int?\n  minPricePoisha     Int\n  maxPricePoisha     Int\n  currency           String    @default(\"BDT\")\n  /// Free-text scope note, e.g. \"Split & window AC up to 1.5 ton\".\n  scopeNote          String?\n  minDurationMinutes Int       @default(60)\n  isActive           Boolean   @default(true)\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n  service         Service         @relation(fields: [serviceId], references: [id], onDelete: Restrict)\n  bookings        Booking[]\n\n  @@unique([providerProfileId, serviceId])\n  @@index([serviceId, isActive])\n  @@index([providerProfileId, isActive])\n  @@map(\"provider_services\")\n}\n\nmodel ProviderServiceArea {\n  id                String   @id @default(cuid())\n  providerProfileId String\n  locationId        String\n  radiusKm          Int      @default(8)\n  travelFeePoisha   Int      @default(0)\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n  location        Location        @relation(fields: [locationId], references: [id], onDelete: Cascade)\n\n  @@unique([providerProfileId, locationId])\n  @@index([locationId, isActive])\n  @@map(\"provider_service_areas\")\n}\n\n/// Weekly recurring working window, stored as minutes from midnight so there is\n/// no timezone ambiguity in the database.\nmodel ProviderAvailability {\n  id                String   @id @default(cuid())\n  providerProfileId String\n  /// 0 = Sunday ... 6 = Saturday (matches JS Date#getDay, Asia/Dhaka).\n  weekday           Int\n  startMinute       Int\n  endMinute         Int\n  slotMinutes       Int      @default(120)\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n\n  @@unique([providerProfileId, weekday, startMinute, endMinute])\n  @@index([providerProfileId, weekday, isActive])\n  @@map(\"provider_availability\")\n}\n\nmodel ProviderAvailabilityException {\n  id                String   @id @default(cuid())\n  providerProfileId String\n  date              DateTime @db.Date\n  isAvailable       Boolean  @default(false)\n  startMinute       Int?\n  endMinute         Int?\n  reason            String?\n  createdAt         DateTime @default(now())\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n\n  @@unique([providerProfileId, date])\n  @@index([date])\n  @@map(\"provider_availability_exceptions\")\n}\n\nmodel ProviderTimeOff {\n  id                String   @id @default(cuid())\n  providerProfileId String\n  startsAt          DateTime\n  endsAt            DateTime\n  reason            String?\n  createdAt         DateTime @default(now())\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n\n  @@index([providerProfileId, startsAt, endsAt])\n  @@map(\"provider_time_off\")\n}\n\nmodel ProviderPayoutMethod {\n  id                String           @id @default(cuid())\n  providerProfileId String\n  type              PayoutMethodType\n  accountNumber     String\n  accountName       String\n  bankName          String?\n  isPrimary         Boolean          @default(false)\n  isVerified        Boolean          @default(false)\n  verifiedAt        DateTime?\n  createdAt         DateTime         @default(now())\n  deletedAt         DateTime?\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n\n  @@index([providerProfileId, isVerified])\n  @@map(\"provider_payout_methods\")\n}\n\nmodel PortfolioItem {\n  id                String    @id @default(cuid())\n  providerProfileId String\n  serviceId         String?\n  title             String\n  description       String?\n  imageKeys         String[]  @default([])\n  completedAt       DateTime?\n  createdAt         DateTime  @default(now())\n  deletedAt         DateTime?\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n\n  @@index([providerProfileId, createdAt])\n  @@map(\"portfolio_items\")\n}\n\n// ---------------------------------------------------------------------------\n// Booking\n// ---------------------------------------------------------------------------\n\nmodel Booking {\n  id        String @id @default(cuid())\n  /// Human-quotable reference, e.g. FB-7KQ2M4. Shown to both sides and to\n  /// support, so it must be short and unambiguous.\n  reference String @unique\n\n  customerId        String\n  providerProfileId String\n  serviceId         String\n  providerServiceId String?\n  addressId         String?\n\n  // ---- snapshot of what was agreed at booking time -------------------------\n  serviceNameEn   String\n  serviceNameBn   String\n  categoryNameEn  String\n  providerName    String\n  providerPhone   String\n  addressSnapshot Json\n  areaName        String\n  districtName    String\n  latitude        Float?\n  longitude       Float?\n\n  // ---- money ---------------------------------------------------------------\n  quotedMinPoisha       Int\n  quotedMaxPoisha       Int\n  /// The number both sides agreed to. For RANGE pricing this is null until the\n  /// provider quotes; the customer sees the range, never a silently higher total.\n  agreedPricePoisha     Int?\n  basePricePoisha       Int\n  extrasPoisha          Int       @default(0)\n  travelFeePoisha       Int       @default(0)\n  discountPoisha        Int       @default(0)\n  totalPoisha           Int\n  commissionPoisha      Int\n  providerEarningPoisha Int\n  currency              String    @default(\"BDT\")\n  priceMode             PriceMode\n\n  // ---- schedule & state ----------------------------------------------------\n  status                BookingStatus @default(REQUESTED)\n  scheduledAt           DateTime\n  scheduledEndAt        DateTime?\n  acceptedAt            DateTime?\n  onTheWayAt            DateTime?\n  arrivedAt             DateTime?\n  startedAt             DateTime?\n  completedAt           DateTime?\n  cancelledAt           DateTime?\n  cancelledBy           BookingActor?\n  cancellationReason    String?\n  cancellationFeePoisha Int           @default(0)\n  noShowBy              BookingActor?\n  disputedAt            DateTime?\n  /// Response deadline for the provider; an expiry job auto-cancels past it.\n  respondBy             DateTime?\n\n  paymentStatus      PaymentStatus @default(PENDING)\n  paymentMethod      PaymentMethod @default(CASH)\n  customerNote       String?\n  providerNote       String?\n  couponRedemptionId String?\n  referralId         String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  customer        User             @relation(\"CustomerBookings\", fields: [customerId], references: [id], onDelete: Restrict)\n  providerProfile ProviderProfile  @relation(fields: [providerProfileId], references: [id], onDelete: Restrict)\n  service         Service          @relation(fields: [serviceId], references: [id], onDelete: Restrict)\n  providerService ProviderService? @relation(fields: [providerServiceId], references: [id], onDelete: SetNull)\n  address         Address?         @relation(fields: [addressId], references: [id], onDelete: SetNull)\n\n  statusHistory     BookingStatusHistory[]\n  events            BookingEvent[]\n  additionalCharges AdditionalChargeRequest[]\n  messages          Message[]\n  conversation      Conversation?\n  review            Review?\n  payments          Payment[]\n  complaints        Complaint[]\n  disputes          Dispute[]\n  tickets           SupportTicket[]\n  couponRedemption  CouponRedemption?         @relation(\"BookingCoupon\")\n  referral          Referral?                 @relation(\"ReferralQualifyingBooking\")\n\n  @@index([customerId, status, createdAt])\n  @@index([providerProfileId, status, scheduledAt])\n  @@index([status, respondBy])\n  @@index([status, createdAt])\n  @@index([serviceId, createdAt])\n  @@index([createdAt])\n  @@map(\"bookings\")\n}\n\nmodel BookingStatusHistory {\n  id          String         @id @default(cuid())\n  bookingId   String\n  fromStatus  BookingStatus?\n  toStatus    BookingStatus\n  actor       BookingActor\n  actorUserId String?\n  reason      String?\n  meta        Json?\n  createdAt   DateTime       @default(now())\n\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  actorUser User?   @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@index([bookingId, createdAt])\n  @@map(\"booking_status_history\")\n}\n\n/// Non-status activity on a booking (charge requested, navigated, etc). Powers\n/// the single timeline both parties and support see.\nmodel BookingEvent {\n  id          String       @id @default(cuid())\n  bookingId   String\n  actor       BookingActor\n  actorUserId String?\n  type        String\n  summary     String\n  meta        Json?\n  createdAt   DateTime     @default(now())\n\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  actorUser User?   @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@index([bookingId, createdAt])\n  @@map(\"booking_events\")\n}\n\n/// Providers may never just raise the final price. Any extra cost is a request\n/// the customer sees, and only an APPROVED request is ever added to the total.\nmodel AdditionalChargeRequest {\n  id                String                 @id @default(cuid())\n  bookingId         String\n  requestedByUserId String\n  amountPoisha      Int\n  reason            String\n  status            AdditionalChargeStatus @default(PENDING)\n  customerNote      String?\n  respondedAt       DateTime?\n  respondedByUserId String?\n  createdAt         DateTime               @default(now())\n  updatedAt         DateTime               @updatedAt\n\n  booking     Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  requestedBy User    @relation(\"ChargeRequestedBy\", fields: [requestedByUserId], references: [id], onDelete: Restrict)\n  respondedBy User?   @relation(\"ChargeRespondedBy\", fields: [respondedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([bookingId, status])\n  @@index([requestedByUserId, createdAt])\n  @@map(\"additional_charge_requests\")\n}\n\n// ---------------------------------------------------------------------------\n// Messaging\n// ---------------------------------------------------------------------------\n\nmodel Conversation {\n  id                 String   @id @default(cuid())\n  customerId         String\n  providerProfileId  String\n  bookingId          String?  @unique\n  lastMessageAt      DateTime @default(now())\n  lastMessagePreview String?\n  customerUnread     Int      @default(0)\n  providerUnread     Int      @default(0)\n  isClosed           Boolean  @default(false)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  customer User            @relation(\"ConversationCustomer\", fields: [customerId], references: [id], onDelete: Cascade)\n  provider ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n  booking  Booking?        @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  messages Message[]\n\n  // One thread per customer/provider pair. Without this, upserting a thread\n  // would need a find-then-create race, and a race here means duplicate\n  // conversations for the same pair.\n  @@unique([customerId, providerProfileId])\n  @@index([customerId, lastMessageAt])\n  @@index([providerProfileId, lastMessageAt])\n  @@map(\"conversations\")\n}\n\nmodel Message {\n  id             String      @id @default(cuid())\n  conversationId String\n  senderUserId   String\n  bookingId      String?\n  kind           MessageKind @default(TEXT)\n  body           String\n  attachmentKeys String[]    @default([])\n  readAt         DateTime?\n  createdAt      DateTime    @default(now())\n  deletedAt      DateTime?\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  sender       User         @relation(fields: [senderUserId], references: [id], onDelete: Cascade)\n  booking      Booking?     @relation(fields: [bookingId], references: [id], onDelete: SetNull)\n\n  @@index([conversationId, createdAt])\n  @@index([senderUserId, readAt])\n  @@map(\"messages\")\n}\n\n// ---------------------------------------------------------------------------\n// Reviews\n// ---------------------------------------------------------------------------\n\n/// One review per completed booking, enforced by the unique constraint. This is\n/// the structural guarantee that ratings cannot be invented.\nmodel Review {\n  id                String       @id @default(cuid())\n  bookingId         String       @unique\n  customerId        String\n  providerProfileId String\n  serviceId         String\n  rating            Int\n  title             String?\n  body              String\n  providerReply     String?\n  providerRepliedAt DateTime?\n  status            ReviewStatus @default(PUBLISHED)\n  moderatedByUserId String?\n  moderationNote    String?\n  reportCount       Int          @default(0)\n  createdAt         DateTime     @default(now())\n  updatedAt         DateTime     @updatedAt\n\n  booking         Booking         @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  customer        User            @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n  moderatedBy     User?           @relation(\"ReviewVerifiedBy\", fields: [moderatedByUserId], references: [id], onDelete: SetNull)\n  flags           ReviewFlag[]\n\n  @@index([providerProfileId, status, createdAt])\n  @@index([customerId, createdAt])\n  @@index([status, reportCount])\n  @@map(\"reviews\")\n}\n\nmodel ReviewFlag {\n  id               String    @id @default(cuid())\n  reviewId         String\n  reason           String\n  detail           String?\n  reportedByUserId String?\n  resolvedAt       DateTime?\n  resolution       String?\n  createdAt        DateTime  @default(now())\n\n  review     Review @relation(fields: [reviewId], references: [id], onDelete: Cascade)\n  reportedBy User?  @relation(fields: [reportedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([reviewId])\n  @@index([resolvedAt])\n  @@map(\"review_flags\")\n}\n\n// ---------------------------------------------------------------------------\n// Money\n// ---------------------------------------------------------------------------\n\nmodel Payment {\n  id                   String         @id @default(cuid())\n  bookingId            String\n  customerId           String\n  providerProfileId    String\n  method               PaymentMethod\n  channel              PaymentChannel @default(PROVIDER)\n  amountPoisha         Int\n  commissionPoisha     Int\n  providerAmountPoisha Int\n  refundedPoisha       Int            @default(0)\n  currency             String         @default(\"BDT\")\n  status               PaymentStatus  @default(CREATED)\n  /// Gateway identity. `idempotencyKey` is what makes a retry safe: a duplicate\n  /// create request can never produce a second charge.\n  gateway              String\n  idempotencyKey       String         @unique\n  gatewayPaymentId     String?\n  gatewayOrderId       String?\n  gatewayReference     String?\n  /// Raw gateway response kept for dispute evidence and reconciliation.\n  gatewayPayload       Json?\n  failureCode          String?\n  failureReason        String?\n  paidAt               DateTime?\n  capturedByUserId     String?\n  createdAt            DateTime       @default(now())\n  updatedAt            DateTime       @updatedAt\n\n  booking         Booking         @relation(fields: [bookingId], references: [id], onDelete: Restrict)\n  customer        User            @relation(\"CustomerPayments\", fields: [customerId], references: [id], onDelete: Restrict)\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Restrict)\n  refunds         Refund[]\n  payoutItems     PayoutItem[]\n\n  @@index([bookingId, status])\n  @@index([providerProfileId, status, createdAt])\n  @@index([customerId, createdAt])\n  @@index([status, createdAt])\n  @@map(\"payments\")\n}\n\nmodel Refund {\n  id                String        @id @default(cuid())\n  paymentId         String\n  amountPoisha      Int\n  reason            String\n  status            PaymentStatus @default(PENDING)\n  gatewayRefundId   String?\n  processedByUserId String?\n  processedAt       DateTime?\n  createdAt         DateTime      @default(now())\n\n  payment     Payment @relation(fields: [paymentId], references: [id], onDelete: Restrict)\n  processedBy User?   @relation(fields: [processedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([paymentId, createdAt])\n  @@index([status])\n  @@map(\"refunds\")\n}\n\nmodel Payout {\n  id                String       @id @default(cuid())\n  reference         String       @unique\n  providerProfileId String\n  periodStart       DateTime\n  periodEnd         DateTime\n  grossPoisha       Int\n  commissionPoisha  Int\n  adjustmentPoisha  Int          @default(0)\n  netPoisha         Int\n  currency          String       @default(\"BDT\")\n  status            PayoutStatus @default(PENDING)\n  methodId          String?\n  methodSnapshot    Json?\n  gatewayTransferId String?\n  note              String?\n  processedByUserId String?\n  processedAt       DateTime?\n  createdAt         DateTime     @default(now())\n  updatedAt         DateTime     @updatedAt\n\n  providerProfile ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Restrict)\n  items           PayoutItem[]\n  processedBy     User?           @relation(fields: [processedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([providerProfileId, status, createdAt])\n  @@index([status, createdAt])\n  @@map(\"payouts\")\n}\n\n/// Ties a payout to the exact captured payments it settles, so earnings always\n/// reconcile against real transactions.\nmodel PayoutItem {\n  id           String @id @default(cuid())\n  payoutId     String\n  paymentId    String\n  amountPoisha Int\n\n  payout  Payout  @relation(fields: [payoutId], references: [id], onDelete: Cascade)\n  payment Payment @relation(fields: [paymentId], references: [id], onDelete: Restrict)\n\n  @@unique([payoutId, paymentId])\n  @@index([paymentId])\n  @@map(\"payout_items\")\n}\n\n/// Commission is data, not code. The most specific active rule wins:\n/// service > category > global.\nmodel CommissionRule {\n  id              String    @id @default(cuid())\n  name            String\n  commissionBps   Int\n  serviceId       String?\n  categoryId      String?\n  effectiveFrom   DateTime  @default(now())\n  effectiveTo     DateTime?\n  isActive        Boolean   @default(true)\n  createdByUserId String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  service   Service? @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n  createdBy User?    @relation(fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@index([isActive, effectiveFrom])\n  @@index([serviceId])\n  @@index([categoryId])\n  @@map(\"commission_rules\")\n}\n\n// ---------------------------------------------------------------------------\n// Complaints, disputes, support\n// ---------------------------------------------------------------------------\n\nmodel Complaint {\n  id                String            @id @default(cuid())\n  reference         String            @unique\n  bookingId         String?\n  customerId        String\n  providerProfileId String?\n  against           ComplaintAgainst\n  category          ComplaintCategory\n  subject           String\n  description       String\n  status            ComplaintStatus   @default(OPEN)\n  priority          Priority          @default(NORMAL)\n  assignedToUserId  String?\n  resolution        String?\n  resolutionType    ResolutionType?\n  resolvedAt        DateTime?\n  closedAt          DateTime?\n  createdAt         DateTime          @default(now())\n  updatedAt         DateTime          @updatedAt\n\n  booking         Booking?          @relation(fields: [bookingId], references: [id], onDelete: SetNull)\n  customer        User              @relation(\"ComplaintCustomer\", fields: [customerId], references: [id], onDelete: Restrict)\n  providerProfile ProviderProfile?  @relation(fields: [providerProfileId], references: [id], onDelete: SetNull)\n  assignedTo      User?             @relation(\"ComplaintAssignee\", fields: [assignedToUserId], references: [id], onDelete: SetNull)\n  dispute         Dispute?\n  evidence        DisputeEvidence[]\n  events          ComplaintEvent[]\n\n  @@index([status, priority, createdAt])\n  @@index([customerId, createdAt])\n  @@index([providerProfileId, createdAt])\n  @@index([assignedToUserId, status])\n  @@map(\"complaints\")\n}\n\nmodel Dispute {\n  id                  String        @id @default(cuid())\n  complaintId         String        @unique\n  bookingId           String\n  openedByUserId      String\n  status              DisputeStatus @default(OPEN)\n  claimAmountPoisha   Int\n  awardedAmountPoisha Int?\n  currency            String        @default(\"BDT\")\n  decision            String?\n  decidedByUserId     String?\n  decidedAt           DateTime?\n  openedAt            DateTime      @default(now())\n  closedAt            DateTime?\n\n  complaint Complaint @relation(fields: [complaintId], references: [id], onDelete: Cascade)\n  booking   Booking   @relation(fields: [bookingId], references: [id], onDelete: Restrict)\n  openedBy  User      @relation(\"DisputeOpenedBy\", fields: [openedByUserId], references: [id], onDelete: Restrict)\n  decidedBy User?     @relation(\"DisputeDecidedBy\", fields: [decidedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([status, openedAt])\n  @@index([bookingId])\n  @@map(\"disputes\")\n}\n\nmodel DisputeEvidence {\n  id               String   @id @default(cuid())\n  complaintId      String\n  uploadedByUserId String\n  kind             String\n  storageKey       String\n  mimeType         String?\n  sizeBytes        Int?\n  note             String?\n  createdAt        DateTime @default(now())\n\n  complaint  Complaint @relation(fields: [complaintId], references: [id], onDelete: Cascade)\n  uploadedBy User      @relation(fields: [uploadedByUserId], references: [id], onDelete: Cascade)\n\n  @@index([complaintId, createdAt])\n  @@map(\"dispute_evidence\")\n}\n\nmodel ComplaintEvent {\n  id          String   @id @default(cuid())\n  complaintId String\n  actorUserId String?\n  actorRole   String?\n  type        String\n  note        String?\n  meta        Json?\n  createdAt   DateTime @default(now())\n\n  complaint Complaint @relation(fields: [complaintId], references: [id], onDelete: Cascade)\n  actor     User?     @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@index([complaintId, createdAt])\n  @@map(\"complaint_events\")\n}\n\nmodel SupportTicket {\n  id               String       @id @default(cuid())\n  reference        String       @unique\n  openedByUserId   String\n  customerId       String?\n  bookingId        String?\n  category         String\n  subject          String\n  priority         Priority     @default(NORMAL)\n  status           TicketStatus @default(OPEN)\n  assignedToUserId String?\n  lastMessageAt    DateTime     @default(now())\n  closedAt         DateTime?\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  openedBy   User            @relation(\"TicketOpener\", fields: [openedByUserId], references: [id], onDelete: Restrict)\n  customer   User?           @relation(\"TicketCustomer\", fields: [customerId], references: [id], onDelete: SetNull)\n  booking    Booking?        @relation(fields: [bookingId], references: [id], onDelete: SetNull)\n  assignedTo User?           @relation(\"TicketAssignee\", fields: [assignedToUserId], references: [id], onDelete: SetNull)\n  messages   TicketMessage[]\n\n  @@index([status, priority, lastMessageAt])\n  @@index([assignedToUserId, status])\n  @@index([openedByUserId, createdAt])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketMessage {\n  id             String   @id @default(cuid())\n  ticketId       String\n  senderUserId   String\n  body           String\n  attachmentKeys String[] @default([])\n  isStaff        Boolean  @default(false)\n  createdAt      DateTime @default(now())\n\n  ticket SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  sender User          @relation(fields: [senderUserId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId, createdAt])\n  @@map(\"ticket_messages\")\n}\n\n// ---------------------------------------------------------------------------\n// Notifications\n// ---------------------------------------------------------------------------\n\nmodel Notification {\n  id        String           @id @default(cuid())\n  userId    String\n  type      NotificationType\n  title     String\n  body      String\n  /// Deep link target, e.g. /pro/bookings/abc\n  href      String?\n  data      Json?\n  readAt    DateTime?\n  createdAt DateTime         @default(now())\n\n  user       User                   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  deliveries NotificationDelivery[]\n\n  @@index([userId, readAt, createdAt])\n  @@index([createdAt])\n  @@map(\"notifications\")\n}\n\nmodel NotificationDelivery {\n  id             String              @id @default(cuid())\n  notificationId String\n  channel        NotificationChannel\n  status         DeliveryStatus      @default(PENDING)\n  providerId     String?\n  error          String?\n  attempts       Int                 @default(0)\n  sentAt         DateTime?\n  createdAt      DateTime            @default(now())\n\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, channel])\n  @@index([status, createdAt])\n  @@map(\"notification_deliveries\")\n}\n\nmodel NotificationPreference {\n  id      String              @id @default(cuid())\n  userId  String\n  channel NotificationChannel\n  event   NotificationType\n  enabled Boolean             @default(true)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, channel, event])\n  @@map(\"notification_preferences\")\n}\n\nmodel PushSubscription {\n  id         String   @id @default(cuid())\n  userId     String\n  endpoint   String   @unique\n  p256dh     String\n  auth       String\n  userAgent  String?\n  lastSeenAt DateTime @default(now())\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ---------------------------------------------------------------------------\n// Coupons & referrals\n// ---------------------------------------------------------------------------\n\nmodel Coupon {\n  id                    String     @id @default(cuid())\n  code                  String     @unique\n  description           String?\n  type                  CouponType\n  /// PERCENT -> basis points of the subtotal. FIXED -> poisha.\n  value                 Int\n  maxDiscountPoisha     Int?\n  minOrderPoisha        Int?\n  startsAt              DateTime\n  endsAt                DateTime\n  maxRedemptions        Int?\n  maxRedemptionsPerUser Int        @default(1)\n  redemptionCount       Int        @default(0)\n  appliesToServiceIds   String[]   @default([])\n  appliesToCategoryIds  String[]   @default([])\n  firstBookingOnly      Boolean    @default(false)\n  isActive              Boolean    @default(true)\n  createdAt             DateTime   @default(now())\n  updatedAt             DateTime   @updatedAt\n\n  redemptions CouponRedemption[]\n\n  @@index([isActive, startsAt, endsAt])\n  @@map(\"coupons\")\n}\n\nmodel CouponRedemption {\n  id             String   @id @default(cuid())\n  couponId       String\n  userId         String\n  bookingId      String   @unique\n  subtotalPoisha Int\n  discountPoisha Int\n  createdAt      DateTime @default(now())\n\n  coupon  Coupon  @relation(fields: [couponId], references: [id], onDelete: Cascade)\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  booking Booking @relation(\"BookingCoupon\", fields: [bookingId], references: [id], onDelete: Cascade)\n\n  @@index([couponId, userId])\n  @@map(\"coupon_redemptions\")\n}\n\nmodel Referral {\n  id                  String         @id @default(cuid())\n  code                String         @unique\n  referrerUserId      String\n  referredUserId      String         @unique\n  status              ReferralStatus @default(PENDING)\n  rewardPoisha        Int            @default(0)\n  qualifyingBookingId String?        @unique\n  qualifiedAt         DateTime?\n  rewardedAt          DateTime?\n  createdAt           DateTime       @default(now())\n\n  referrer User     @relation(\"Referrer\", fields: [referrerUserId], references: [id], onDelete: Cascade)\n  referred User     @relation(\"Referred\", fields: [referredUserId], references: [id], onDelete: Cascade)\n  booking  Booking? @relation(\"ReferralQualifyingBooking\", fields: [qualifyingBookingId], references: [id], onDelete: SetNull)\n\n  @@index([referrerUserId, status])\n  @@index([status, createdAt])\n  @@map(\"referrals\")\n}\n\n// ---------------------------------------------------------------------------\n// Platform operations\n// ---------------------------------------------------------------------------\n\n/// Business rules live here so cancellation windows, fees and commission\n/// defaults are configurable from the admin panel instead of hard-coded.\nmodel Setting {\n  key             String   @id\n  value           Json\n  group           String   @default(\"general\")\n  description     String?\n  updatedByUserId String?\n  updatedAt       DateTime @updatedAt\n\n  updatedBy User? @relation(fields: [updatedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([group])\n  @@map(\"settings\")\n}\n\nmodel AuditLog {\n  id          String      @id @default(cuid())\n  actorUserId String?\n  actorRole   String?\n  action      AuditAction\n  entityType  String\n  entityId    String\n  summary     String?\n  before      Json?\n  after       Json?\n  ip          String?\n  userAgent   String?\n  createdAt   DateTime    @default(now())\n\n  actor User? @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@index([entityType, entityId, createdAt])\n  @@index([actorUserId, createdAt])\n  @@index([action, createdAt])\n  @@map(\"audit_logs\")\n}\n\n/// Durable queue. Workers claim rows with SELECT ... FOR UPDATE SKIP LOCKED, so\n/// multiple workers can run safely without a dedicated broker.\nmodel Job {\n  id          String    @id @default(cuid())\n  type        JobType\n  status      JobStatus @default(PENDING)\n  payload     Json\n  priority    Int       @default(0)\n  attempts    Int       @default(0)\n  maxAttempts Int       @default(3)\n  runAt       DateTime  @default(now())\n  lockedAt    DateTime?\n  lockedBy    String?\n  lastError   String?\n  /// Collapses duplicate work, e.g. reminder-per-booking-per-day.\n  dedupeKey   String?   @unique\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([status, runAt, priority])\n  @@index([type, status])\n  @@map(\"jobs\")\n}\n\n/// Real demand signal, not decoration: what people actually searched for and\n/// whether they found a provider. Feeds launch-city planning.\nmodel SearchQueryLog {\n  id                String   @id @default(cuid())\n  userId            String?\n  rawQuery          String\n  normalizedQuery   String\n  detectedLanguage  String?\n  locationId        String?\n  resultCount       Int      @default(0)\n  clickedProviderId String?\n  createdAt         DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([normalizedQuery, createdAt])\n  @@index([createdAt])\n  @@map(\"search_query_logs\")\n}\n",
